45	+using Microsoft.EntityFrameworkCore;
46	+using seed_b_backend.Api.Data;
47	+using seed_b_backend.Api.Domain;
48	+
49	+namespace seed_b_backend.Api.Application;
50	+
51	+public class RatingService(AppDbContext context)
52	+{
53	+    public async Task<RatingAggregate?> SubmitRatingAsync(
54	+        string productId,
55	+        string authorName,
56	+        int score,
57	+        CancellationToken ct = default)
58	+    {
59	+        var productExists = await context.Products.AnyAsync(p => p.Id == productId, ct);
60	+        if (!productExists)
61	+        {
62	+            return null;
63	+        }
64	+
65	+        var updatedRows = await context.Ratings
66	+            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
67	+            .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
68	+
69	+        if (updatedRows == 0)
70	+        {
71	+            var newRating = new Rating { ProductId = productId, AuthorName = authorName, Score = score };
72	+            context.Ratings.Add(newRating);
73	+            try
74	+            {
75	+                await context.SaveChangesAsync(ct);
76	+            }
77	+            catch (DbUpdateException)
78	+            {
79	+                // Eine gleichzeitige Bewertungsabgabe für dasselbe (ProductId, AuthorName)
80	+                // hat ihre Zeile zwischen unserem ExecuteUpdateAsync (traf nichts) und
81	+                // diesem Add eingefügt — der DB-Unique-Constraint (AD-5) lehnt unseren
82	+                // Insert ab, statt still zu duplizieren. Fallback: Update, das jetzt
83	+                // garantiert genau diese Zeile trifft.
84	+                context.Entry(newRating).State = EntityState.Detached;
85	+                await context.Ratings
86	+                    .Where(r => r.ProductId == productId && r.AuthorName == authorName)
87	+                    .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
88	+            }
89	+        }
90	+
91	+        var scores = await context.Ratings
92	+            .Where(r => r.ProductId == productId)
93	+            .Select(r => r.Score)
94	+            .ToListAsync(ct);
95	+
96	+        return new RatingAggregate
97	+        {
98	+            AverageRating = scores.Count > 0 ? scores.Average() : null,
99	+            RatingCount = scores.Count
100	+        };
101	+    }
102	+}
