14	
15	  protected readonly product = signal<ProductDetailModel | null>(null);
16	  protected readonly notFound = signal(false);
17	  protected readonly loading = signal(true);
18	
19	  protected readonly authorName = signal('');
20	  protected readonly score = signal<number | null>(null);
21	  protected readonly submitting = signal(false);
22	  protected readonly submitError = signal<string | null>(null);
23	  protected readonly submitSuccess = signal(false);
