28	      this.notFound.set(true);
29	      this.loading.set(false);
30	      return;
31	    }
32	    this.productApi.getProduct(id).subscribe({
33	      next: (product) => {
34	        this.product.set(product);
35	        this.loading.set(false);
36	      },
37	      error: () => {
38	        this.notFound.set(true);
39	        this.loading.set(false);
40	      }
41	    });
42	  }
