53	    const current = this.product();
54	    const author = this.authorName().trim();
55	    const scoreValue = this.score();
56	    if (!current || !author || scoreValue === null) {
57	      this.submitError.set('Bitte Sternewert und Namen angeben.');
58	      this.submitSuccess.set(false);
59	      return;
60	    }
61	
62	    this.submitting.set(true);
63	    this.submitError.set(null);
64	    this.submitSuccess.set(false);
