66	    this.productApi.submitRating(current.id, { authorName: author, score: scoreValue }).subscribe({
67	      next: (result) => {
68	        this.product.set({ ...current, averageRating: result.averageRating, ratingCount: result.ratingCount });
69	        this.submitting.set(false);
70	        this.submitSuccess.set(true);
71	        this.authorName.set('');
72	        this.score.set(null);
73	      },
74	      error: () => {
75	        this.submitting.set(false);
